export {createSync,mergeCloud,captureTask,restoreTask,normalizeHistory,newId} from './sync.js?v=65adec0897fe27e0';
import {normalizeHistory,newId} from './sync.js?v=65adec0897fe27e0';
export const day = (now=new Date()) => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
export function loadState(storage) {
 try {
  const s=JSON.parse(storage.getItem('word-learning-v1'));
  if(s?.version===1 && Array.isArray(s.items) && s.items.every(x=>typeof x.id==='string'&&typeof x.word==='string'&&typeof x.meaning==='string')) return s;
 } catch {}
 return {version:1,items:[]};
}
export function addItem(state,item,now=new Date()) {
 const old=state.items.find(x=>x.id===item.id);
 if(old) return false;
 state.items.push({...item,studyDay:day(now),due:now.toISOString(),stage:0});
 return true;
}
export function rateItem(item,rating,now=new Date()) {
 if(!['remember','uncertain','forgot'].includes(rating)) throw new Error('invalid_rating');
 item.stage=rating==='remember'?Math.min((item.stage||0)+1,3):0;
 const days=rating==='remember'?[1,1,3,7][item.stage]:1;
 item.due=new Date(+now+days*86400000).toISOString();
 normalizeHistory(item);item.lastReviewEventId=newId();item.history=[...(item.history||[]),{id:item.lastReviewEventId,at:now.toISOString(),rating}];item.lastRating=rating;item.lastReview=now.toISOString();item.reviewUpdatedAt=new Date(Math.max(+now,(Date.parse(item.reviewUpdatedAt)||0)+1)).toISOString();item.reviewRevision=item.reviewUpdatedAt+':'+Math.random().toString(36).slice(2);
 // Self-report schedules practice; it never sets a mastered flag.
 return rating!=='remember';
}

export function mergeStates(local, remote) {
 const items=new Map(remote.items.map(x=>[x.id,x]));
 for(const item of local.items){
  const other=items.get(item.id);
  if(!other){items.set(item.id,item);continue;}
  const newer=(Date.parse(other.reviewUpdatedAt||other.lastReview)||0)>(Date.parse(item.reviewUpdatedAt||item.lastReview)||0)?other:item;
  const content=(Date.parse(other.meaningUpdatedAt)||0)>(Date.parse(item.meaningUpdatedAt)||0)?other:item;
  items.set(item.id,{...newer,meaning:content.meaning,originalMeaning:content.originalMeaning,meaningUpdatedAt:content.meaningUpdatedAt,studyDay:[item.studyDay,other.studyDay].filter(Boolean).sort().at(-1)});
 }
 return {version:1,items:[...items.values()]};
}

// A resumable, single-word learning journey. Only unfinished words enter recap.
export function getFlow(state, now=new Date()) {
 const f=state.flow;
 if(f&&Array.isArray(f.studied)&&Array.isArray(f.pending)&&Array.isArray(f.reviewed)&&Array.isArray(f.reviewIds)&&Array.isArray(f.retried)) return f;
 return state.flow={day:day(now),active:false,phase:'home',studied:[],pending:[],reviewed:[],reviewIds:[],retried:[],position:0,currentId:null,reviewKind:null};
}
export function learnWord(flow,id) {
 if(!flow.studied.includes(id))flow.studied.push(id);if(!flow.pending.includes(id)&&!flow.reviewed.includes(id))flow.pending.push(id);
 flow.currentId=null;flow.phase=flow.pending.length>=3?'group':'input';
}
export function beginReview(flow,ids,kind) {
 flow.reviewIds=[...new Set(ids)];flow.reviewInitialCount=flow.reviewIds.length;flow.position=0;flow.retried=[];flow.reviewKind=kind;
 flow.phase=flow.reviewIds.length?'review':kind==='finish'?'finished':'home';
}
export function advanceReview(flow,id,again) {
 if(again&&!flow.retried.includes(id)){flow.retried.push(id);flow.reviewIds.push(id);}
 flow.position++;
 if(flow.position<flow.reviewIds.length)return false;
 if(['group','finish'].includes(flow.reviewKind)){
  const completed=new Set(flow.reviewIds);flow.pending=flow.pending.filter(x=>!completed.has(x));
  flow.reviewed=[...new Set([...flow.reviewed,...completed])];
 }
 flow.phase=flow.reviewKind==='group'?'choice':flow.reviewKind==='finish'?'finished':'home';
 return true;
}

