// Small manually reviewed spelling alignment to Merriam-Webster main US pronunciation.
// Sources and exclusions: discussions/data/reviewed-syllable-sources.json.
// https://www.merriam-webster.com/grammar/word-division-dots-and-syllable-pronunciation-hyphens
const reviewedSyllables={"banana":["ba","na","na"],"computer":["com","pu","ter"],"afternoon":["af","ter","noon"],"morning":["mor","ning"],"animal":["a","ni","mal"],"elephant":["e","le","phant"],"potato":["po","ta","to"],"tomato":["to","ma","to"],"remember":["re","mem","ber"],"beautiful":["beau","ti","ful"],"basketball":["ba","sket","ball"],"football":["foot","ball"],"classroom":["class","room"],"bedroom":["bed","room"],"homework":["home","work"],"teacher":["tea","cher"],"music":["mu","sic"],"paper":["pa","per"],"open":["o","pen"],"over":["o","ver"],"window":["win","dow"],"astronaut":["a","stro","naut"],"avocado":["a","vo","ca","do"],"together":["to","ge","ther"]};
export function pronunciationParts(word) {
 const tokens=word.match(/[A-Za-z]+(?:'[A-Za-z]+)?|[^A-Za-z]+/g)||[];
 if(!tokens.length||tokens.some(x=>/[A-Za-z]/.test(x)&&!verifiedMonosyllables.has(x.toLowerCase())&&!Object.hasOwn(reviewedSyllables,x.toLowerCase())))return null;
 return tokens.flatMap(token=>{const parts=reviewedSyllables[token.toLowerCase()];if(!parts)return [token];let offset=0;return parts.map(part=>{const text=token.slice(offset,offset+part.length);offset+=part.length;return text;});});
}

export function reviewProgress(flow) {
 const initial=flow.reviewInitialCount??Math.max(0,flow.reviewIds.length-flow.retried.length);
 const modes={group:'三词回顾',finish:'收尾回顾',due:'到期复习',today:'今日回顾'};
 const label=modes[flow.reviewKind]||'回顾';
 return flow.position<initial?`${label} · 第 ${flow.position+1} / ${initial} 词`:`${label} · 再练 ${flow.position-initial+1} / ${flow.reviewIds.length-initial}`;
}
export function senseOptions(meaning) {
 const pos=/^(?:[a-z]+\.\s*)+/i;
 const parts=meaning.split(/\r?\n/).flatMap(line=>{
  const text=line.trim(),prefix=text.match(pos)?.[0]||'';
  return text.slice(prefix.length).split(/[；;]/).map(x=>x.trim()).filter(Boolean).map(x=>pos.test(x)?x:prefix+x);
 }).filter(Boolean);
 return parts.length>1&&parts.every(x=>/[\u3400-\u9fff]/.test(x))?[meaning,...new Set(parts)]:[meaning];
}

export function commitDraft(state,flow,now=new Date()) {
 const draft=flow.draft;if(!draft||!draft.meaning.trim())return false;
 const old=state.items.find(x=>x.id===draft.id);
 const added=addItem(state,draft,now);if(added){const item=state.items.at(-1);item.learningStatus='initial';item.createdAt||=now.toISOString();item.due=null;}
 if(old&&old.meaning!==draft.meaning){throw new Error('Use a separate sense ID before committing a different meaning');}
 const alreadyQueued=flow.recapQueue?.some(task=>task.pending?.includes(draft.id)||task.reviewIds?.includes(draft.id));
 flow.waiting=flow.waiting?.filter(id=>id!==draft.id)||[];if(old?.learningStatus==='waiting')old.learningStatus='initial';if(!alreadyQueued&&!old?.lastReview)learnWord(flow,draft.id);else flow.phase='input';flow.draft=null;flow.lookupDraft=null;
 if(flow.phase==='group')beginReview(flow,flow.pending,'group');
 return true;
}
export function recordReview(state,flow,id,rating,now=new Date()) {
 const item=state.items.find(x=>x.id===id);if(!item)return;
 normalizeHistory(item);const before=JSON.parse(JSON.stringify(flow));delete before.undo;
 const schedule={learningStatus:item.learningStatus,stage:item.stage,due:item.due,lastRating:item.lastRating,lastReview:item.lastReview,lastReviewEventId:item.lastReviewEventId,reviewUpdatedAt:item.reviewUpdatedAt,history:JSON.parse(JSON.stringify(item.history||[]))};
 item.reviewBase||=Object.fromEntries(['stage','due','lastRating','lastReview','lastReviewEventId','learningStatus'].map(k=>[k,schedule[k]??null]));
 const again=rateItem(item,rating,now);item.learningStatus='scheduled';if(again&&['due','today'].includes(flow.reviewKind))item.due=now.toISOString();advanceReview(flow,id,again);
 item.history.at(-1).schedule={stage:item.stage,due:item.due,lastRating:item.lastRating,lastReview:item.lastReview,lastReviewEventId:item.lastReviewEventId,learningStatus:item.learningStatus};
 flow.undo={id,before,schedule,eventId:item.history.at(-1).id,expectedRevision:item.reviewRevision||item.reviewUpdatedAt};flow.recall=null;
}
export function undoReview(state,flow,now=new Date()) {
 const undo=flow.undo;if(!undo)return false;const item=state.items.find(x=>x.id===undo.id);
 if(!item||(item.reviewRevision||item.reviewUpdatedAt||item.lastReview)!==undo.expectedRevision){flow.undo=null;return false;}
 item.reviewBase||=Object.fromEntries(['stage','due','lastRating','lastReview','lastReviewEventId','learningStatus'].map(k=>[k,undo.schedule[k]??null]));
 for(const key of ['lastRating','lastReview','lastReviewEventId'])if(undo.schedule[key]===undefined)undo.schedule[key]=null;
 normalizeHistory(item);normalizeHistory(undo.schedule);delete undo.schedule.removedReviewIds;const keep=new Set((undo.schedule.history||[]).map(h=>h.id));
 const eventId=undo.eventId||item.history.filter(h=>!keep.has(h.id)&&h.at===item.lastReview&&h.rating===item.lastRating).at(-1)?.id;
 item.removedReviewIds=[...new Set([...(item.removedReviewIds||[]),...(eventId?[eventId]:[])])];
 const retained=item.history.filter(h=>h.id!==eventId);
 const later=retained.filter(h=>h.schedule&&!keep.has(h.id)&&Date.parse(h.at)>(Date.parse(undo.schedule.lastReview)||0)).sort((a,b)=>a.at.localeCompare(b.at)).at(-1);
 if(later)Object.assign(undo.schedule,later.schedule);undo.schedule.history=retained;
 const revision=new Date(Math.max(+now,(Date.parse(item.reviewUpdatedAt)||0)+1)).toISOString();Object.assign(item,undo.schedule,{reviewUpdatedAt:revision,reviewRevision:revision+':'+Math.random().toString(36).slice(2)});
 for(const key of Object.keys(flow))delete flow[key];Object.assign(flow,undo.before,{undo:null});return true;
}


// B2: one item remains one independently scheduled meaning. Legacy IDs stay stable.
export const wordKey = word => word.trim().replace(/\s+/g,' ').toLowerCase();
export function senseStatus(item,now=new Date()) {return !item.lastReview ? 'new' : Date.parse(item.due)<=+now ? 'due' : 'later';}
export function dueItems(items,now=new Date()) {return items.filter(x=>!['waiting','initial'].includes(x.learningStatus)&&Date.parse(x.due)<=+now).sort((a,b)=>(Date.parse(a.due)-Date.parse(b.due))||a.id.localeCompare(b.id));}
export function wordGroups(items) {const map=new Map();for(const item of items){const key=wordKey(item.word);if(!map.has(key))map.set(key,{word:item.word,items:[]});map.get(key).items.push(item);}return [...map.values()];}
export function searchBook(items,{query='',status='',list='',since='',sort='recent',page=0}={},now=new Date()) {
 const q=query.trim().toLowerCase();let groups=wordGroups(items).filter(g=>g.items.some(x=>(!q||(x.word+' '+x.meaning).toLowerCase().includes(q))&&(!status||(status==='due'?Date.parse(x.due)<=+now:senseStatus(x,now)===status))&&(!list||(x.lists||[x.studyDay]).includes(list))&&(!since||(x.createdAt&&Number.isFinite(Date.parse(x.createdAt))?day(new Date(x.createdAt)):(x.studyDay||''))>=since)));
 groups.sort((a,b)=>sort==='az'?a.word.localeCompare(b.word,'en'):Math.max(...b.items.map(x=>Date.parse(x.createdAt||x.studyDay)||0))-Math.max(...a.items.map(x=>Date.parse(x.createdAt||x.studyDay)||0))||a.word.localeCompare(b.word,'en'));
 const pages=Math.max(1,Math.ceil(groups.length/20)),current=Math.min(Math.max(0,page),pages-1);return {total:groups.length,pages,page:current,rows:groups.slice(current*20,current*20+20)};
}
export function prepareSense(state,draft,list=day(),now=new Date()) {
 const same=state.items.find(x=>wordKey(x.word)===wordKey(draft.word)&&x.meaning.trim()===draft.meaning.trim());
 if(same)return {...same,lists:[...new Set([...(same.lists||[same.studyDay]).filter(Boolean),list])]};
 const exists=state.items.some(x=>x.id===draft.id);return {...draft,id:exists?draft.id+'-sense-'+(+now)+'-'+Math.random().toString(36).slice(2):draft.id,createdAt:now.toISOString(),lists:[list],stage:0,lastReview:null,lastRating:null,history:[]};
}
